function combinationSum(candidates, target) {
  const result = [];
  const path = [];
  const decide = (i, left) => {
    if (left === 0) { result.push([...path]); return; }
    if (i === candidates.length || left < 0) return;
    path.push(candidates[i]);                // take candidates[i] (and maybe again)
    decide(i, left - candidates[i]);
    path.pop();
    decide(i + 1, left);                     // or move on to the next candidate
  };
  decide(0, target);
  return result;
}

List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> result = new ArrayList<>();
    decide(candidates, 0, target, new ArrayList<>(), result);
    return result;
}

void decide(int[] c, int i, int left, List<Integer> path, List<List<Integer>> result) {
    if (left == 0) { result.add(new ArrayList<>(path)); return; }
    if (i == c.length || left < 0) return;
    path.add(c[i]);                              // take c[i] (and maybe again)
    decide(c, i, left - c[i], path, result);
    path.remove(path.size() - 1);
    decide(c, i + 1, left, path, result);        // or move on to the next candidate
}

void decide(vector<int>& c, int i, int left, vector<int>& path, vector<vector<int>>& result) {
    if (left == 0) { result.push_back(path); return; }
    if (i == (int)c.size() || left < 0) return;
    path.push_back(c[i]);                        // take c[i] (and maybe again)
    decide(c, i, left - c[i], path, result);
    path.pop_back();
    decide(c, i + 1, left, path, result);        // or move on to the next candidate
}

