function combinationSum(candidates, target) {
  const sorted = [...candidates].sort((a, b) => a - b);
  const result = [];
  const path = [];
  const build = (start, left) => {
    if (left === 0) {                          // exactly the target: one answer
      result.push([...path]);
      return;
    }
    for (let i = start; i < sorted.length; i++) {
      if (sorted[i] > left) break;             // too big, and so is everything after it
      path.push(sorted[i]);
      build(i, left - sorted[i]);              // i, not i + 1: it may be used again
      path.pop();
    }
  };
  build(0, target);
  return result;
}

List<List<Integer>> combinationSum(int[] candidates, int target) {
    int[] nums = candidates.clone();
    Arrays.sort(nums);
    List<List<Integer>> result = new ArrayList<>();
    build(nums, 0, target, new ArrayList<>(), result);
    return result;
}

void build(int[] nums, int start, int left, List<Integer> path, List<List<Integer>> result) {
    if (left == 0) {                             // exactly the target: one answer
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        if (nums[i] > left) break;               // too big, and so is everything after it
        path.add(nums[i]);
        build(nums, i, left - nums[i], path, result);   // i, not i + 1: it may be used again
        path.remove(path.size() - 1);
    }
}

void build(vector<int>& nums, int start, int left, vector<int>& path, vector<vector<int>>& result) {
    if (left == 0) {                             // exactly the target: one answer
        result.push_back(path);
        return;
    }
    for (int i = start; i < (int)nums.size(); i++) {
        if (nums[i] > left) break;               // too big, and so is everything after it
        path.push_back(nums[i]);
        build(nums, i, left - nums[i], path, result);   // i, not i + 1: it may be used again
        path.pop_back();
    }
}

vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
    vector<int> nums = candidates;
    sort(nums.begin(), nums.end());
    vector<vector<int>> result;
    vector<int> path;
    build(nums, 0, target, path, result);
    return result;
}
